from __future__ import annotations

import json
import re
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
MARK = re.compile(r"«([^»]+)»")
BASIC_KANJI = set((ROOT / "docs/minna-import-2026-09-16/basic-kanji-book-1.txt").read_text(encoding="utf-8"))


def furigana_flag(word: str) -> str:
    return "Y" if any(ch not in BASIC_KANJI for ch in re.findall(r"[一-龯]", word)) else "N"

