def parse_examples(raw: str) -> tuple[str, str]:
    parts = raw.split("§")
    if len(parts) != 3 or any(len(MARK.findall(p)) != 1 for p in parts):
        raise ValueError(f"Нужны три примера с одной целевой формой: {raw}")
    marked = [MARK.sub(lambda m: f"<span class='study-word'>{m.group(1)}</span>", p) for p in parts]
    blanks = [MARK.sub("_____", p) for p in parts]
    return "<br>".join(marked), "<br>".join(blanks)


def main() -> None:
    by_topic: dict[str, set[str]] = {}
    created = []
    for line in DATA.splitlines():
        word, topic, reading, translation, jp, ru, note, kanji, level, kinds = line.split("|")
        example, blank = parse_examples(jp)
        translations = ru.split("§")
        if len(translations) != 3:
            raise ValueError(word)
        card_path = ROOT / "Карточки" / topic / f"{word}.json"
        by_topic.setdefault(topic, set()).add(word)
        if card_path.exists():
            card = json.loads(card_path.read_text(encoding="utf-8"))
            if card.get("Подсказка") != HINTS[word] or card.get("Показать фуригану") != furigana_flag(word):
                card["Подсказка"] = HINTS[word]
                card["Показать фуригану"] = furigana_flag(word)
                card_path.write_text(json.dumps(card, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            continue
        tags = [topic, *kinds.split(","), level]
        card = {
            "Слово": word,
            "Чтение": reading,
            "Перевод": translation,
            "Подсказка": HINTS[word],
            "Пример": example,
            "Пример без слова": blank,
            "Пример перевод": "<br>".join(translations),
            "Картинка": f"masterpiece, best quality, anime illustration, square 1:1, exactly one person, {translations[2]}, visual focus: {translation}, physical object or clear action, natural pose, warm light, no text, no letters, no watermark. Negative: extra people, text, letters, logo, bad anatomy.",
            "Произношение": "",
            "Заметки": note,
            "Кандзи-разбор": kanji,
            "Показать фуригану": furigana_flag(word),
            "Теги": tags,
        }
        card_path.parent.mkdir(parents=True, exist_ok=True)
        card_path.write_text(json.dumps(card, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
        created.append(str(card_path.relative_to(ROOT)))
    for topic, words in by_topic.items():
        path = ROOT / "Слова" / topic
        existing = path.read_text(encoding="utf-8").splitlines() if path.exists() else []
        path.write_text("\n".join(sorted({x.strip() for x in existing if x.strip()} | words)) + "\n", encoding="utf-8")
    print(f"Создано JSON: {len(created)}; тем: {len(by_topic)}")
    for path in created:
        print(path)


if __name__ == "__main__":
    main()
